/**
 * "Blocked by" links between issues. Every method takes `orgId` first; the
 * blocker lookups join `issues` so archived and closed blockers are decided in
 * one place.
 *
 * Must call (do not reimplement): livePredicate, orgPredicate
 */
import { and, asc, eq, inArray, notInArray } from "drizzle-orm";
import { getDb, issueDependencies, issues } from "@/server/db";
import { toIsoTimestamp } from "@/types/common";
import { CLOSED_ISSUE_STATUSES } from "@/types/issue";
import { livePredicate, orgPredicate } from "./base-repository";
import { compact } from "./_paging";
import { brandId, toIssue, toIssueDependency } from "./_mappers";
import { listLabelsForIssues } from "./label-repository";
import type { IssueId, OrgId, UserId } from "@/types/common";
import type { Issue, IssueDependency } from "@/types/issue";

export async function findDependency(
  orgId: OrgId,
  issueId: IssueId,
  blockerId: IssueId,
): Promise<IssueDependency | null> {
  const row = getDb()
    .select()
    .from(issueDependencies)
    .where(
      and(
        orgPredicate(issueDependencies.orgId, orgId),
        eq(issueDependencies.issueId, issueId),
        eq(issueDependencies.blockerId, blockerId),
      ),
    )
    .get();
  return row ? toIssueDependency(row) : null;
}

/**
 * Records "`issueId` is blocked by `blockerId`" unless it would close a loop.
 *
 * The existing-link lookup, the cycle walk and the insert run in one
 * synchronous transaction: two racing calls (A←B and B←A) must not both pass
 * the cycle check before either has written. Returns `null` when the link
 * would create a cycle; `created` is `false` when the link already existed.
 */
export async function insertDependencyUnlessCyclic(
  orgId: OrgId,
  issueId: IssueId,
  blockerId: IssueId,
  createdBy: UserId,
): Promise<{ dependency: IssueDependency; created: boolean } | null> {
  return getDb().transaction(
    (tx) => {
      const existing = tx
        .select()
        .from(issueDependencies)
        .where(
          and(
            orgPredicate(issueDependencies.orgId, orgId),
            eq(issueDependencies.issueId, issueId),
            eq(issueDependencies.blockerId, blockerId),
          ),
        )
        .get();
      if (existing) {
        return { dependency: toIssueDependency(existing), created: false };
      }

      // The new edge closes a loop iff `issueId` already sits somewhere in the
      // chain of blockers above `blockerId` — archived and closed issues
      // included, since the links through them still exist.
      const seen = new Set<string>([blockerId]);
      let frontier: string[] = [blockerId];
      while (frontier.length > 0) {
        const next: string[] = [];
        const edges = tx
          .select({ blockerId: issueDependencies.blockerId })
          .from(issueDependencies)
          .where(
            and(
              orgPredicate(issueDependencies.orgId, orgId),
              inArray(issueDependencies.issueId, frontier),
            ),
          )
          .all();
        for (const edge of edges) {
          if (edge.blockerId === issueId) return null;
          if (!seen.has(edge.blockerId)) {
            seen.add(edge.blockerId);
            next.push(edge.blockerId);
          }
        }
        frontier = next;
      }

      const row = tx
        .insert(issueDependencies)
        .values({
          orgId,
          issueId,
          blockerId,
          createdBy,
          createdAt: toIsoTimestamp(new Date()),
        })
        .returning()
        .get();
      return { dependency: toIssueDependency(row), created: true };
    },
    { behavior: "immediate" },
  );
}

/** `true` when a link existed and was removed. */
export async function deleteDependency(
  orgId: OrgId,
  issueId: IssueId,
  blockerId: IssueId,
): Promise<boolean> {
  const rows = getDb()
    .delete(issueDependencies)
    .where(
      and(
        orgPredicate(issueDependencies.orgId, orgId),
        eq(issueDependencies.issueId, issueId),
        eq(issueDependencies.blockerId, blockerId),
      ),
    )
    .returning({ issueId: issueDependencies.issueId })
    .all();
  return rows.length > 0;
}

/** Live blockers of `issueId` (open or closed), by issue number. */
export async function listBlockers(
  orgId: OrgId,
  issueId: IssueId,
): Promise<readonly Issue[]> {
  const rows = getDb()
    .select({ issue: issues })
    .from(issueDependencies)
    .innerJoin(issues, eq(issues.id, issueDependencies.blockerId))
    .where(
      and(
        ...compact(
          orgPredicate(issueDependencies.orgId, orgId),
          orgPredicate(issues.orgId, orgId),
          eq(issueDependencies.issueId, issueId),
          livePredicate(issues.archivedAt, {}),
        ),
      ),
    )
    .orderBy(asc(issues.number), asc(issues.id))
    .all()
    .map((row) => row.issue);

  const labels = await listLabelsForIssues(
    orgId,
    rows.map((row) => brandId<IssueId>(row.id)),
  );
  return rows.map((row) =>
    toIssue(row, (labels[row.id] ?? []).map((label) => label.id)),
  );
}

/** Blockers of `issueId` that are neither archived nor done/canceled. */
export async function listOpenBlockerIds(
  orgId: OrgId,
  issueId: IssueId,
): Promise<readonly IssueId[]> {
  const rows = getDb()
    .select({ id: issues.id })
    .from(issueDependencies)
    .innerJoin(issues, eq(issues.id, issueDependencies.blockerId))
    .where(
      and(
        ...compact(
          orgPredicate(issueDependencies.orgId, orgId),
          orgPredicate(issues.orgId, orgId),
          eq(issueDependencies.issueId, issueId),
          livePredicate(issues.archivedAt, {}),
          notInArray(issues.status, [...CLOSED_ISSUE_STATUSES]),
        ),
      ),
    )
    .orderBy(asc(issues.number), asc(issues.id))
    .all();
  return rows.map((row) => brandId<IssueId>(row.id));
}

/** Ids of every issue with a link saying it is blocked by `blockerId`. */
export async function listBlockedIssueIds(
  orgId: OrgId,
  blockerId: IssueId,
): Promise<readonly IssueId[]> {
  const rows = getDb()
    .select({ issueId: issueDependencies.issueId })
    .from(issueDependencies)
    .where(
      and(
        orgPredicate(issueDependencies.orgId, orgId),
        eq(issueDependencies.blockerId, blockerId),
      ),
    )
    .all();
  return rows.map((row) => brandId<IssueId>(row.issueId));
}

