/**
 * Issue dependencies ("blocked by" links): who may record them, the rules a
 * link must satisfy, and the error the completion gate in `IssueService`
 * raises while an issue still has open blockers.
 *
 * Must call (do not reimplement): assertCan, assertOrgScope, assertNotArchived
 */
import { assertCan } from "@/lib/permissions";
import { assertNotArchived } from "@/lib/soft-delete";
import { assertOrgScope } from "@/lib/tenant";
import * as dependencyRepo from "@/server/repositories/issue-dependency-repository";
import * as issueRepo from "@/server/repositories/issue-repository";
import { issueResource, requireFound } from "./_support";
import type { IssueId, OrgId } from "@/types/common";
import type { Issue, IssueDependency } from "@/types/issue";
import type { Actor } from "@/types/member";

/**
 * Raised instead of completing an issue that still has open blockers.
 * `blockerIds` names exactly the blockers that are neither archived nor
 * done/canceled, by issue number.
 */
export class IssueBlockedError extends Error {
  readonly code = "conflict" as const;

  constructor(
    readonly blockerIds: readonly IssueId[],
    readonly issueId?: IssueId,
  ) {
    super(
      `${issueId === undefined ? "Issue" : `Issue ${issueId}`} is blocked by ${blockerIds.length} open issue${blockerIds.length === 1 ? "" : "s"}: ${blockerIds.join(", ")}`,
    );
    this.name = "IssueBlockedError";
  }
}

/** A link that could never be satisfied: an issue blocking itself, or a loop. */
class IssueDependencyError extends Error {
  readonly code = "conflict" as const;

  constructor(message: string) {
    super(message);
    this.name = "IssueDependencyError";
  }
}

interface BlockerInput {
  orgId: OrgId;
  issueId: IssueId;
  blockerId: IssueId;
}

/**
 * Records "`issueId` is blocked by `blockerId`". Editing the blocked issue is
 * the permission that matters — the blocker is only referenced, not changed.
 * Re-adding an existing link returns it rather than failing.
 */
export async function addBlocker(
  actor: Actor,
  input: BlockerInput,
): Promise<IssueDependency> {
  assertOrgScope(actor, input.orgId);

  const issue = requireFound(
    await issueRepo.findIssueById(input.orgId, input.issueId),
    "Issue",
    input.issueId,
  );
  assertCan(actor, "issue:update", issueResource(issue));

  const blocker = requireFound(
    await issueRepo.findIssueById(input.orgId, input.blockerId),
    "Issue",
    input.blockerId,
  );

  if (issue.id === blocker.id) {
    throw new IssueDependencyError(`Issue ${issue.id} cannot block itself`);
  }
  assertNotArchived("Issue", issue.id, issue);
  assertNotArchived("Issue", blocker.id, blocker);

  const result = await dependencyRepo.insertDependencyUnlessCyclic(
    input.orgId,
    issue.id,
    blocker.id,
    actor.userId,
  );
  if (result === null) {
    throw new IssueDependencyError(
      `Issue ${issue.id} cannot be blocked by ${blocker.id}: that would create a dependency cycle`,
    );
  }

  return result.dependency;
}

/**
 * Deletes one link. Only the blocked issue has to exist — a link to a blocker
 * that has since vanished must still be removable. `false` means no such link.
 */
export async function removeBlocker(
  actor: Actor,
  input: BlockerInput,
): Promise<boolean> {
  assertOrgScope(actor, input.orgId);

  const issue = requireFound(
    await issueRepo.findIssueById(input.orgId, input.issueId),
    "Issue",
    input.issueId,
  );
  assertCan(actor, "issue:update", issueResource(issue));

  return dependencyRepo.deleteDependency(
    input.orgId,
    issue.id,
    input.blockerId,
  );
}

/** Blockers of an issue that are not archived — open and closed alike. */
export async function listBlockers(
  actor: Actor,
  orgId: OrgId,
  issueId: IssueId,
): Promise<readonly Issue[]> {
  assertOrgScope(actor, orgId);

  const issue = requireFound(
    await issueRepo.findIssueById(orgId, issueId),
    "Issue",
    issueId,
  );
  assertCan(actor, "issue:read", issueResource(issue));

  return dependencyRepo.listBlockers(orgId, issue.id);
}

