/**
 * Tells an assignee when the last open blocker of their issue closes.
 *
 * A blocker closes when it reaches `done`/`canceled` or is archived while
 * still open; both arrive as domain events, so this hangs off the bus like the
 * other reactive concerns instead of being called from `IssueService`.
 *
 * Must call (do not reimplement): subscribe, notify
 */
import { subscribe } from "@/lib/event-bus";
import { isLive } from "@/lib/soft-delete";
import * as dependencyRepo from "@/server/repositories/issue-dependency-repository";
import * as issueRepo from "@/server/repositories/issue-repository";
import { CLOSED_ISSUE_STATUSES } from "@/types/issue";
import { notify } from "./notification-service";
import type { IssueId, OrgId, UserId } from "@/types/common";
import type { Unsubscribe } from "@/types/event";
import type { IssueStatus } from "@/types/issue";

function isClosedStatus(status: IssueStatus): boolean {
  return CLOSED_ISSUE_STATUSES.includes(status);
}

export function registerIssueUnblockListeners(): Unsubscribe {
  const offs: Unsubscribe[] = [
    subscribe("issue.status_changed", async (payload) => {
      // Only open → closed unblocks; done → canceled and reopening do not.
      if (isClosedStatus(payload.from) || !isClosedStatus(payload.to)) return;
      await notifyUnblocked(payload.orgId, [payload.issueId], payload.actorId);
    }),
    subscribe("issue.archived", async (payload) => {
      // Archiving leaves the status alone, so it says how the blocker was left.
      const issue = await issueRepo.findIssueById(
        payload.orgId,
        payload.issueId,
      );
      if (issue === null || isClosedStatus(issue.status)) return;
      await notifyUnblocked(payload.orgId, [payload.issueId], payload.actorId);
    }),
    subscribe("project.archived", async (payload) => {
      const closedIds = payload.archivedOpenIssueIds ?? [];
      if (closedIds.length === 0) return;
      await notifyUnblocked(payload.orgId, closedIds, payload.actorId);
    }),
  ];

  return () => {
    for (const off of offs) off();
  };
}

/**
 * For every issue blocked by one of `closedIds` that is still live and open,
 * has an assignee and no open blocker left, notifies that assignee once.
 */
async function notifyUnblocked(
  orgId: OrgId,
  closedIds: readonly IssueId[],
  actorId: UserId | null,
): Promise<void> {
  const candidateIds = new Set<IssueId>();
  for (const closedId of closedIds) {
    for (const blockedId of await dependencyRepo.listBlockedIssueIds(
      orgId,
      closedId,
    )) {
      candidateIds.add(blockedId);
    }
  }

  for (const blockedId of candidateIds) {
    const blocked = await issueRepo.findIssueById(orgId, blockedId);
    if (blocked === null || !isLive(blocked)) continue;
    if (isClosedStatus(blocked.status) || blocked.assigneeId === null) continue;

    const stillOpen = await dependencyRepo.listOpenBlockerIds(orgId, blockedId);
    if (stillOpen.length > 0) continue;

    await notify(orgId, "issue_unblocked", [blocked.assigneeId], {
      title: "An issue was unblocked",
      body: `Issue "${blocked.title}" no longer has any open blockers`,
      href: `/issues/${blocked.id}`,
      actorId,
    });
  }
}
