/**
 * Issue dependencies: link rules, the completion gate and the unblocked
 * notification that rides the event bus.
 */
import { afterAll, beforeAll, describe, expect, it, vi } from "vitest";

vi.mock("@/lib/logger", async () => (await import("../server/_support/doubles/misc")).loggerModule);

import { subscribe } from "@/lib/event-bus";
import { PermissionDeniedError } from "@/lib/permissions";
import { AlreadyArchivedError } from "@/lib/soft-delete";
import { TenantScopeError } from "@/lib/tenant";
import * as depRepo from "@/server/repositories/issue-dependency-repository";
import * as preferenceRepo from "@/server/repositories/notification-preference-repository";
import { registerEventHandlers } from "@/server/services/event-registry";
import {
  addBlocker,
  IssueBlockedError,
  listBlockers,
  removeBlocker,
} from "@/server/services/issue-dependency-service";
import * as issueService from "@/server/services/issue-service";
import { listNotifications } from "@/server/services/notification-service";
import * as projectService from "@/server/services/project-service";
import { NotFoundError } from "@/server/services/_support";
import { createTenant, issueInput, useTemporaryDatabase } from "../server/_support/fixtures";
import type { Tenant } from "../server/_support/fixtures";
import type { IssueId, UserId } from "@/types/common";
import type { Issue, IssueStatus } from "@/types/issue";

let cleanup: () => void;
let tenant: Tenant;
let other: Tenant;

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
  tenant = await createTenant("deps", "growth");
  other = await createTenant("depsother", "growth");
  registerEventHandlers();
});

afterAll(() => {
  cleanup();
});

async function makeIssue(
  assigneeId: UserId | null = null,
  t: Tenant = tenant,
): Promise<Issue> {
  return issueService.createIssue(
    t.actors.owner,
    issueInput(t.org.id, t.project.id, { title: "Dependency subject", assigneeId }),
  );
}

async function link(issue: Issue, blocker: Issue) {
  return addBlocker(tenant.actors.member, {
    orgId: tenant.org.id,
    issueId: issue.id,
    blockerId: blocker.id,
  });
}

async function setStatus(issue: Issue, status: IssueStatus, actor = tenant.actors.owner) {
  return issueService.changeIssueStatus(actor, {
    orgId: tenant.org.id,
    issueId: issue.id,
    status,
  });
}

async function unblockedFor(userId: UserId) {
  const page = await listNotifications(tenant.actors.owner, {
    orgId: tenant.org.id,
    recipientId: userId,
    unreadOnly: false,
    kind: ["issue_unblocked"],
    limit: 50,
    cursor: null,
  });
  return page.items;
}

describe("addBlocker / removeBlocker / listBlockers", () => {
  it("records a link stamped with the acting user and is idempotent", async () => {
    const a = await makeIssue();
    const b = await makeIssue();

    const first = await link(a, b);
    expect(first).toMatchObject({
      orgId: tenant.org.id,
      issueId: a.id,
      blockerId: b.id,
      createdBy: tenant.userIds.member,
    });

    const again = await addBlocker(tenant.actors.admin, {
      orgId: tenant.org.id,
      issueId: a.id,
      blockerId: b.id,
    });
    expect(again).toEqual(first);
    expect(await listBlockers(tenant.actors.owner, tenant.org.id, a.id)).toHaveLength(1);
  });

  it("rejects self-blocks and cycles, storing nothing", async () => {
    const a = await makeIssue();
    const b = await makeIssue();
    const c = await makeIssue();

    await expect(link(a, a)).rejects.toThrow();

    await link(a, b);
    await expect(link(b, a)).rejects.toThrow();

    await link(b, c);
    await expect(link(c, a)).rejects.toThrow();

    expect(await depRepo.findDependency(tenant.org.id, c.id, a.id)).toBeNull();
    expect(await depRepo.findDependency(tenant.org.id, b.id, a.id)).toBeNull();
    expect(await depRepo.findDependency(tenant.org.id, a.id, a.id)).toBeNull();
  });

  it("does not let racing calls close a loop", async () => {
    const a = await makeIssue();
    const b = await makeIssue();

    const results = await Promise.allSettled([link(a, b), link(b, a)]);
    expect(results.filter((r) => r.status === "fulfilled")).toHaveLength(1);
  });

  it("enforces tenant scope, existence and permission", async () => {
    const a = await makeIssue();
    const b = await makeIssue();
    const foreign = await makeIssue(null, other);
    const ghost = "01HZZZGHOSTGHOSTGHOSTGHOST" as IssueId;

    await expect(
      addBlocker(other.actors.member, { orgId: tenant.org.id, issueId: a.id, blockerId: b.id }),
    ).rejects.toBeInstanceOf(TenantScopeError);
    await expect(
      removeBlocker(other.actors.member, { orgId: tenant.org.id, issueId: a.id, blockerId: b.id }),
    ).rejects.toBeInstanceOf(TenantScopeError);
    await expect(
      listBlockers(other.actors.member, tenant.org.id, a.id),
    ).rejects.toBeInstanceOf(TenantScopeError);

    for (const blockerId of [ghost, foreign.id]) {
      await expect(
        addBlocker(tenant.actors.member, { orgId: tenant.org.id, issueId: a.id, blockerId }),
      ).rejects.toBeInstanceOf(NotFoundError);
    }
    await expect(
      addBlocker(tenant.actors.member, { orgId: tenant.org.id, issueId: foreign.id, blockerId: b.id }),
    ).rejects.toBeInstanceOf(NotFoundError);
    await expect(
      removeBlocker(tenant.actors.member, { orgId: tenant.org.id, issueId: ghost, blockerId: b.id }),
    ).rejects.toBeInstanceOf(NotFoundError);
    await expect(
      listBlockers(tenant.actors.member, tenant.org.id, ghost),
    ).rejects.toBeInstanceOf(NotFoundError);

    await expect(
      addBlocker(tenant.actors.viewer, { orgId: tenant.org.id, issueId: a.id, blockerId: b.id }),
    ).rejects.toBeInstanceOf(PermissionDeniedError);
    await link(a, b);
    await expect(
      removeBlocker(tenant.actors.viewer, { orgId: tenant.org.id, issueId: a.id, blockerId: b.id }),
    ).rejects.toBeInstanceOf(PermissionDeniedError);
    expect(await depRepo.findDependency(tenant.org.id, a.id, b.id)).not.toBeNull();
    // A viewer may read.
    expect(await listBlockers(tenant.actors.viewer, tenant.org.id, a.id)).toHaveLength(1);
  });

  it("rejects archived issues on either side", async () => {
    const a = await makeIssue();
    const b = await makeIssue();
    const c = await makeIssue();
    await issueService.archiveIssue(tenant.actors.owner, tenant.org.id, b.id);

    await expect(link(a, b)).rejects.toBeInstanceOf(AlreadyArchivedError);
    await expect(link(b, c)).rejects.toBeInstanceOf(AlreadyArchivedError);
  });

  it("removes links, reporting whether one existed", async () => {
    const a = await makeIssue();
    const b = await makeIssue();
    await link(a, b);

    const input = { orgId: tenant.org.id, issueId: a.id, blockerId: b.id };
    expect(await removeBlocker(tenant.actors.member, input)).toBe(true);
    expect(await removeBlocker(tenant.actors.member, input)).toBe(false);
  });

  it("lists non-archived blockers by issue number", async () => {
    const a = await makeIssue();
    const b1 = await makeIssue();
    const b2 = await makeIssue();
    const b3 = await makeIssue();
    await link(a, b3);
    await link(a, b1);
    await link(a, b2);
    await setStatus(b2, "done");
    await issueService.archiveIssue(tenant.actors.owner, tenant.org.id, b3.id);

    const listed = await listBlockers(tenant.actors.member, tenant.org.id, a.id);
    expect(listed.map((issue) => issue.id)).toEqual([b1.id, b2.id]);
  });
});

describe("completion gate", () => {
  it("refuses done while a blocker is open and lists exactly the open ones", async () => {
    const a = await makeIssue();
    const open1 = await makeIssue();
    const open2 = await makeIssue();
    const finished = await makeIssue();
    const archived = await makeIssue();
    for (const blocker of [open1, open2, finished, archived]) await link(a, blocker);
    await setStatus(finished, "done");
    await issueService.archiveIssue(tenant.actors.owner, tenant.org.id, archived.id);

    const seen: unknown[] = [];
    const off = subscribe("issue.status_changed", (payload) => {
      seen.push(payload);
    });
    try {
      const error = await setStatus(a, "done").catch((e: unknown) => e);
      expect(error).toBeInstanceOf(IssueBlockedError);
      expect((error as IssueBlockedError).code).toBe("conflict");
      expect([...(error as IssueBlockedError).blockerIds].sort()).toEqual(
        [open1.id, open2.id].sort(),
      );

      await expect(
        issueService.moveIssue(tenant.actors.owner, {
          orgId: tenant.org.id,
          issueId: a.id,
          toStatus: "done",
          toIndex: 0,
        }),
      ).rejects.toBeInstanceOf(IssueBlockedError);
      expect(seen).toHaveLength(0);
    } finally {
      off();
    }

    const after = await issueService.getIssue(tenant.actors.owner, tenant.org.id, a.id);
    expect(after.issue.status).toBe("backlog");

    // Other transitions are fine, and done is fine once the blockers close.
    expect((await setStatus(a, "canceled")).status).toBe("canceled");
    await setStatus(a, "todo");
    await setStatus(open1, "canceled");
    await setStatus(open2, "done");
    expect((await setStatus(a, "done")).status).toBe("done");
  });
});

describe("issue_unblocked notification", () => {
  it("notifies the assignee when the last open blocker is closed", async () => {
    const assignee = tenant.userIds.admin;
    const blocked = await makeIssue(assignee);
    const b1 = await makeIssue();
    const b2 = await makeIssue();
    await link(blocked, b1);
    await link(blocked, b2);

    const before = (await unblockedFor(assignee)).length;

    await setStatus(b1, "done", tenant.actors.member);
    expect(await unblockedFor(assignee)).toHaveLength(before);

    await setStatus(b2, "canceled", tenant.actors.member);
    const rows = (await unblockedFor(assignee)).filter(
      (row) => row.href === `/issues/${blocked.id}`,
    );
    expect(rows).toHaveLength(1);
    expect(rows[0]).toMatchObject({
      kind: "issue_unblocked",
      actorId: tenant.userIds.member,
      recipientId: assignee,
    });

    // closed → closed never notifies.
    await setStatus(b2, "done", tenant.actors.member);
    expect(
      (await unblockedFor(assignee)).filter((row) => row.href === `/issues/${blocked.id}`),
    ).toHaveLength(1);

    // reopen and close again: unblocks again.
    await setStatus(b2, "todo", tenant.actors.member);
    await setStatus(b2, "done", tenant.actors.member);
    expect(
      (await unblockedFor(assignee)).filter((row) => row.href === `/issues/${blocked.id}`),
    ).toHaveLength(2);
  });

  it("notifies when the last open blocker is archived, but not for closed ones", async () => {
    const assignee = tenant.userIds.viewer;
    const blocked = await makeIssue(assignee);
    const done = await makeIssue();
    const open = await makeIssue();
    await link(blocked, done);
    await link(blocked, open);
    await setStatus(done, "done");

    await issueService.archiveIssue(tenant.actors.member, tenant.org.id, open.id);
    const rows = (await unblockedFor(assignee)).filter(
      (row) => row.href === `/issues/${blocked.id}`,
    );
    expect(rows).toHaveLength(1);
    expect(rows[0]?.actorId).toBe(tenant.userIds.member);

    // Archiving an already-closed blocker never notifies.
    const blocked2 = await makeIssue(assignee);
    const closedBlocker = await makeIssue();
    await link(blocked2, closedBlocker);
    await setStatus(closedBlocker, "done");
    const count = (await unblockedFor(assignee)).length;
    await issueService.archiveIssue(tenant.actors.member, tenant.org.id, closedBlocker.id);
    expect(await unblockedFor(assignee)).toHaveLength(count);
  });

  it("skips unassigned, closed, archived and self-triggered cases", async () => {
    const assignee = tenant.userIds.admin;
    const unassigned = await makeIssue(null);
    const closedBlocked = await makeIssue(assignee);
    const archivedBlocked = await makeIssue(assignee);
    const ownAction = await makeIssue(tenant.userIds.member);
    const blocker = await makeIssue();
    for (const issue of [unassigned, closedBlocked, archivedBlocked, ownAction]) {
      await link(issue, blocker);
    }
    await setStatus(closedBlocked, "canceled");
    await issueService.archiveIssue(tenant.actors.owner, tenant.org.id, archivedBlocked.id);

    const before = (await unblockedFor(assignee)).length;
    const memberBefore = (await unblockedFor(tenant.userIds.member)).length;
    await setStatus(blocker, "done", tenant.actors.member);

    expect(await unblockedFor(assignee)).toHaveLength(before);
    expect(await unblockedFor(tenant.userIds.member)).toHaveLength(memberBefore);
  });

  it("honours a muted preference and never fires when a link is removed", async () => {
    const assignee = tenant.userIds.owner;
    await preferenceRepo.upsertPreference({
      orgId: tenant.org.id,
      userId: assignee,
      kind: "issue_unblocked",
      inApp: false,
      email: false,
      digestOnly: false,
    });
    const blocked = await makeIssue(assignee);
    const blocker = await makeIssue();
    await link(blocked, blocker);

    const before = (await unblockedFor(assignee)).length;
    await setStatus(blocker, "done", tenant.actors.member);
    expect(await unblockedFor(assignee)).toHaveLength(before);

    const other2 = await makeIssue(tenant.userIds.admin);
    const blocker2 = await makeIssue();
    await link(other2, blocker2);
    const adminBefore = (await unblockedFor(tenant.userIds.admin)).length;
    await removeBlocker(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: other2.id,
      blockerId: blocker2.id,
    });
    await setStatus(blocker2, "done", tenant.actors.member);
    expect(await unblockedFor(tenant.userIds.admin)).toHaveLength(adminBefore);
  });

  it("notifies when a project archive cascades over an open blocker", async () => {
    const project = await projectService.createProject(tenant.actors.admin, {
      orgId: tenant.org.id,
      name: "Cascade deps",
      slug: "cascade-deps",
      key: "CDP",
      description: null,
      visibility: "org",
      leadId: null,
      color: "#6366f1",
      targetDate: null,
    });
    const assignee = tenant.userIds.viewer;
    const blocker = await issueService.createIssue(
      tenant.actors.owner,
      issueInput(tenant.org.id, project.id, { title: "Cascaded blocker" }),
    );
    const blocked = await makeIssue(assignee);
    await link(blocked, blocker);

    const before = (await unblockedFor(assignee)).length;
